-- Seed: Labels stock (department 'Labels', group 'All', 705 rows).
-- From final_labels_stock_4th_sept…xlsx. Idempotent; never touches photo_path.

on conflict (department, thaily, sr) do update set
  name=excluded.name, inventory=excluded.inventory, uom=excluded.uom,
  qty_pcs=excluded.qty_pcs, extra=excluded.extra;
